param(
    [string]$SourcePath="$PSScriptRoot\..\assets\concept\SENTRY\OBS-07_SENTRY_source.jpg",
    [string]$OutputDirectory="$PSScriptRoot\..\assets\enemies\sector_07\sentry\sprites"
)
$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Drawing
$a=[Drawing.Bitmap].Assembly.Location;$r=Split-Path $a;$refs=@($a,(Join-Path $r 'System.Drawing.Primitives.dll'),(Join-Path $r 'System.Private.Windows.GdiPlus.dll'),(Join-Path $r 'System.Private.Windows.Core.dll'),(Join-Path $r 'System.Private.CoreLib.dll'),(Join-Path $r 'System.Runtime.dll'),(Join-Path $r 'System.Collections.dll'))
Add-Type -ReferencedAssemblies $refs -TypeDefinition @'
using System;using System.Collections;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.IO;
public static class SentryConceptBuilder{
 class C{public int Id,N,X0,Y0,X1,Y1;public double CX{get{return(X0+X1)/2.0;}}}
 static bool Bg(Color c){int hi=Math.Max(c.R,Math.Max(c.G,c.B)),lo=Math.Min(c.R,Math.Min(c.G,c.B));return hi<=20&&hi-lo<=7;}
 static Bitmap Cut(Bitmap s,Rectangle q){var b=s.Clone(q,PixelFormat.Format32bppArgb);int w=b.Width,h=b.Height;var v=new bool[w*h];var z=new int[w*h];int p=0,n=0;for(int x=0;x<w;x++)foreach(int y in new[]{0,h-1}){int i=y*w+x;if(!v[i]&&Bg(b.GetPixel(x,y))){v[i]=true;z[n++]=i;}}for(int y=0;y<h;y++)foreach(int x in new[]{0,w-1}){int i=y*w+x;if(!v[i]&&Bg(b.GetPixel(x,y))){v[i]=true;z[n++]=i;}}int[] dx={1,-1,0,0},dy={0,0,1,-1};while(p<n){int i=z[p++],x=i%w,y=i/w;b.SetPixel(x,y,Color.Transparent);for(int d=0;d<4;d++){int xx=x+dx[d],yy=y+dy[d];if(xx<0||yy<0||xx>=w||yy>=h)continue;int j=yy*w+xx;if(!v[j]&&Bg(b.GetPixel(xx,yy))){v[j]=true;z[n++]=j;}}}for(int y=0;y<h;y++)for(int x=0;x<w;x++){var c=b.GetPixel(x,y);int hi=Math.Max(c.R,Math.Max(c.G,c.B));b.SetPixel(x,y,c.A==0||hi<10?Color.Transparent:Color.FromArgb(255,c.R,c.G,c.B));}return b;}
 static C[] Parts(Bitmap b,int count,out int[] labels){int w=b.Width,h=b.Height;labels=new int[w*h];int[] q=new int[w*h],dx={-1,0,1,-1,1,-1,0,1},dy={-1,-1,-1,0,0,1,1,1};var all=new ArrayList();int id=0;for(int sy=0;sy<h;sy++)for(int sx=0;sx<w;sx++){int st=sy*w+sx;if(labels[st]!=0||b.GetPixel(sx,sy).A==0)continue;id++;int a=0,e=0;q[e++]=st;labels[st]=id;var c=new C{Id=id,X0=sx,X1=sx,Y0=sy,Y1=sy};while(a<e){int k=q[a++],x=k%w,y=k/w;c.N++;c.X0=Math.Min(c.X0,x);c.X1=Math.Max(c.X1,x);c.Y0=Math.Min(c.Y0,y);c.Y1=Math.Max(c.Y1,y);for(int d=0;d<8;d++){int xx=x+dx[d],yy=y+dy[d];if(xx<0||yy<0||xx>=w||yy>=h)continue;int j=yy*w+xx;if(labels[j]==0&&b.GetPixel(xx,yy).A>0){labels[j]=id;q[e++]=j;}}}if(c.N>120)all.Add(c);}var take=new C[count];var used=new bool[all.Count];for(int k=0;k<count;k++){int best=-1;for(int i=0;i<all.Count;i++)if(!used[i]&&(best<0||((C)all[i]).N>((C)all[best]).N))best=i;if(best<0)throw new InvalidDataException("Not enough Sentry silhouettes");used[best]=true;take[k]=(C)all[best];}for(int i=0;i<count-1;i++)for(int j=i+1;j<count;j++)if(take[j].CX<take[i].CX){var t=take[i];take[i]=take[j];take[j]=t;}return take;}
 static Rectangle Bounds(Bitmap b){int x0=b.Width,y0=b.Height,x1=-1,y1=-1;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).A>0){x0=Math.Min(x0,x);x1=Math.Max(x1,x);y0=Math.Min(y0,y);y1=Math.Max(y1,y);}if(x1<0)throw new InvalidDataException("Empty Sentry frame");return Rectangle.FromLTRB(x0,y0,x1+1,y1+1);}
 public static void Build(string src,string dst,int count,int sx,int sy,int sw,int sh,int fw,bool death){using(var sheet=new Bitmap(src)){var f=new Bitmap[count];var b=new Rectangle[count];if(!death){using(var row=Cut(sheet,new Rectangle(sx,sy,sw,sh))){int[] labels;var parts=Parts(row,count,out labels);for(int i=0;i<count;i++){var c=parts[i];f[i]=new Bitmap(c.X1-c.X0+1,c.Y1-c.Y0+1,PixelFormat.Format32bppArgb);for(int y=c.Y0;y<=c.Y1;y++)for(int x=c.X0;x<=c.X1;x++)if(labels[y*row.Width+x]==c.Id)f[i].SetPixel(x-c.X0,y-c.Y0,row.GetPixel(x,y));b[i]=Bounds(f[i]);}}}else for(int i=0;i<count;i++){int x0=sx+(int)Math.Floor((double)i*sw/count),x1=sx+(int)Math.Floor((double)(i+1)*sw/count);f[i]=Cut(sheet,new Rectangle(x0,sy,x1-x0,sh));b[i]=Bounds(f[i]);}
 int[] hs=new int[count];int mw=1;for(int i=0;i<count;i++){hs[i]=b[i].Height;mw=Math.Max(mw,b[i].Width);}int rh;if(death)rh=hs[0];else{var s=(int[])hs.Clone();Array.Sort(s);rh=s[s.Length/2];}double scale=Math.Min(48.0/rh,(fw-4.0)/mw);using(var atlas=new Bitmap(count*fw,64,PixelFormat.Format32bppArgb))using(var g=Graphics.FromImage(atlas)){g.Clear(Color.Transparent);g.CompositingMode=CompositingMode.SourceCopy;g.InterpolationMode=InterpolationMode.NearestNeighbor;g.PixelOffsetMode=PixelOffsetMode.Half;for(int i=0;i<count;i++){var q=b[i];int tw=Math.Max(1,(int)Math.Round(q.Width*scale)),th=Math.Max(1,(int)Math.Round(q.Height*scale));int tx=i*fw+(fw-tw)/2,ty=(64-th)/2;g.DrawImage(f[i],new Rectangle(tx,ty,tw,th),q,GraphicsUnit.Pixel);}for(int i=0;i<count;i++)f[i].Dispose();g.Dispose();for(int y=0;y<atlas.Height;y++)for(int x=0;x<atlas.Width;x++){var c=atlas.GetPixel(x,y);atlas.SetPixel(x,y,c.A<128?Color.Transparent:Color.FromArgb(255,c.R,c.G,c.B));}Directory.CreateDirectory(Path.GetDirectoryName(dst));atlas.Save(dst,ImageFormat.Png);}}}
}
'@
$animations=[ordered]@{
 hover_idle=@(6,190,0,960,145,64,$false);move=@(4,240,145,800,140,64,$false);pulse_shot=@(5,175,280,950,125,64,$false);triple_pulse=@(7,80,405,1120,132,64,$false);hit=@(3,350,535,570,145,64,$false);death=@(6,115,678,1140,170,96,$true)
}
$src=[IO.Path]::GetFullPath($SourcePath);$out=[IO.Path]::GetFullPath($OutputDirectory);foreach($e in $animations.GetEnumerator()){$v=$e.Value;$dst=Join-Path $out ($e.Key+'.png');[SentryConceptBuilder]::Build($src,$dst,[int]$v[0],[int]$v[1],[int]$v[2],[int]$v[3],[int]$v[4],[int]$v[5],[bool]$v[6]);Write-Output("BUILT sentry/{0}: {1}x64"-f$e.Key,([int]$v[0]*[int]$v[5]))}
